import 'package:cozy_life_adventure/game/dialogue/dialogue_choice_eligibility.dart';
import 'package:cozy_life_adventure/game/dialogue/dialogue_model.dart';
import 'package:cozy_life_adventure/game/state/player_event_journal.dart';
import 'package:cozy_life_adventure/game/state/runtime_game_state.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../support/game_content_test_support.dart';

void main() {
  test(
    'choice conditions use affinity facts flags nodes and player events',
    () {
      final journal = PlayerEventJournal().record(
        kind: PlayerEventKind.resourceGathered,
        subjectId: 'moonflower',
        activeSeconds: 10,
      );
      const choice = DialogueChoice(
        id: 'conditional-choice',
        text: 'Respond',
        endsConversation: true,
        conditions: DialogueConditions(
          minimumAffinity: 2,
          maximumAffinity: 4,
          requiredFlags: {'ready'},
          excludedFlags: {'blocked'},
          requiredFactIds: {'known'},
          unknownFactIds: {'secret'},
          requiredSeenNodeIds: {'intro'},
          unseenNodeIds: {'ending'},
          events: [
            PlayerEventCondition(
              kind: PlayerEventKind.resourceGathered,
              subjectId: 'moonflower',
            ),
          ],
        ),
      );
      final relationship = NpcRelationshipState(
        npcId: 'npc-01',
        affinity: 2,
        flags: const {'ready'},
        learnedFactIds: const {'known'},
        seenDialogueIds: const {'intro'},
      );

      final available = const DialogueChoiceEligibilityService().evaluate(
        choice: choice,
        relationship: relationship,
        journal: journal,
        activePlaySeconds: 10,
        inventoryCounts: const {},
        itemCatalog: testGameContent.items,
      );
      final unavailable = const DialogueChoiceEligibilityService().evaluate(
        choice: choice,
        relationship: relationship.copyWith(flags: const {'ready', 'blocked'}),
        journal: journal,
        activePlaySeconds: 10,
        inventoryCounts: const {},
        itemCatalog: testGameContent.items,
      );

      expect(available.isAvailable, isTrue);
      expect(unavailable.reason, DialogueChoiceIneligibility.conditions);
    },
  );
}
